def write(root, use_android_stubs=True):
    groups = [XPOSED] + ([ANDROID] if use_android_stubs else [])
    paths = []
    for group in groups:
        for name, body in group.items():
            p = Path(root) / name; p.parent.mkdir(parents=True, exist_ok=True); p.write_text(body); paths.append(str(p))
    return paths
